import {HOSPITALS,PROVIDERS,REGION_ROUTES,hospitalsForCourse,HSO_SOURCE,LOGO_SOURCE,DIRECTORY_NOTES} from './hso-data.js?v=3.1.0';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountHospitalUI({openModal,tour}){
 const badge=document.createElement('div');badge.id='partner-badge';badge.innerHTML='<img src="assets/sykehuspartner.png" alt="Sykehuspartner"><span>HELSE SØR-ØST · FJELLCUPEN</span>';
 document.querySelector('.course-callout').prepend(badge);
 const button=document.createElement('button');button.id='hospitals-btn';button.className='text-btn';button.textContent='Sykehusløypa';document.querySelector('.top-actions').prepend(button);
 const readout=document.createElement('aside');readout.id='hospital-readout';readout.className='hidden';readout.setAttribute('aria-label','Sykehus langs banen');readout.innerHTML='<span></span><strong></strong><small></small>';document.querySelector('#hud').append(readout);
 button.onclick=()=>{openModal('Hele regionen. Én fjellcup.',`<p>${HOSPITALS.length} navngitte sykehus og behandlingssteder, fordelt på tre baner. Alle ni sykehusforetakene og de fire private ideelle samarbeidssykehusene i Helse Sør-Østs oversikt er representert.</p><p class="board-note">Bygningene er stiliserte spillmodeller i et oppdiktet landskap. De er ikke arkitektoniske kopier, og løypa er ikke et geografisk kart. Dette er ikke en komplett katalog over alle DPS, poliklinikker eller private avtaleleverandører.</p><div class="hospital-directory">${REGION_ROUTES.map((name,i)=>`<details ${i===0?'open':''}><summary>BANE ${i+1} · ${esc(name)} <small>${hospitalsForCourse(i).length} steder</small></summary><button class="secondary hospital-tour" data-tour="${i}">Rolig, automatisk utsiktstur →</button><ol>${hospitalsForCourse(i).map(h=>`<li><strong>${esc(h.name)}</strong><span>${esc(PROVIDERS[h.provider].name)}${PROVIDERS[h.provider].nonprofit?' · privat ideell samarbeidspartner':''}</span>${h.note!=='Sykehus'?`<small>${esc(h.note)}</small>`:''}<a href="${esc(PROVIDERS[h.provider].source)}" target="_blank" rel="noopener noreferrer">Kilde ↗</a></li>`).join('')}</ol></details>`).join('')}</div><h3>Oppdatert sykehusstruktur</h3>${DIRECTORY_NOTES.map(n=>`<p class="board-note">${esc(n.text)} <a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">Kilde ↗</a></p>`).join('')}<p class="board-note">Oversikt kontrollert 16.10.2026. <a href="${HSO_SOURCE}" target="_blank" rel="noopener noreferrer">Helse Sør-Østs behandlingssteder ↗</a></p><h3>Profil og inspirasjon</h3><p class="board-note">Sykehuspartner-logoen er hentet uendret fra <a href="${LOGO_SOURCE}" target="_blank" rel="noopener noreferrer">Helse Sør-Østs offisielle profilside ↗</a>. Den tilhører Sykehuspartner. Uoffisielt læringsspill; ingen godkjenning eller sponsing er hevdet. Kjørefølelsen er inspirert av presisjonsracing som Trackmania, men kode, bilmodeller og fysikk er egenutviklet.</p>`);document.querySelectorAll('[data-tour]').forEach(b=>b.onclick=()=>tour(+b.dataset.tour));};
}
